// Generated by scripts/fit-epicycles.ts against Tailwind 4.3.5. Do not edit.
// A few shade patterns, each carried around the hue wheel by a handful of rotating circles
// (epicycles): sums of cos/sin of whole turns of hue. Each pattern is itself a smooth function of
// shade (a Chebyshev sum), so shade is a real parameter. Lightness is one surface; chroma and hue
// are one complex surface c·e^{i(h − hue)}, so the hue wheel itself is factored out.
const R = Math.PI / 180;

/** Shade-500 hues of the Tailwind families it was fitted to, sorted. */
export const epicyclesHues: number[] = [16.439,25.331,47.604,70.08,86.047,130.85,149.579,162.48,182.503,215.221,237.323,259.815,277.117,292.717,303.9,322.15,354.308];

/** The colour (OKLCH) at a shade from 50 to 950 and a hue in degrees. */
export function epicyclesAt(shade: number, hue: number): { l: number; c: number; h: number } {
  const x = (shade - 500) / 450;
  const T2 = 2 * x * x - 1;
  const T3 = 2 * x * T2 - x;
  const T4 = 2 * x * T3 - T2;
  const T5 = 2 * x * T4 - T3;
  const T6 = 2 * x * T5 - T4;
  const T7 = 2 * x * T6 - T5;
  const T8 = 2 * x * T7 - T6;
  const t = hue * R;
  const c1 = Math.cos(t);
  const s1 = Math.sin(t);
  const c2 = Math.cos(2 * t);
  const s2 = Math.sin(2 * t);
  const c3 = Math.cos(3 * t);
  const s3 = Math.sin(3 * t);
  const c4 = Math.cos(4 * t);
  const s4 = Math.sin(4 * t);
  const c5 = Math.cos(5 * t);
  const s5 = Math.sin(5 * t);
  const c6 = Math.cos(6 * t);
  const s6 = Math.sin(6 * t);
  const c7 = Math.cos(7 * t);
  const s7 = Math.sin(7 * t);
  const c8 = Math.cos(8 * t);
  const s8 = Math.sin(8 * t);

  // lightness: one value per pattern, the circles summed
  const l0 = 0.005616 - 0.05003 * c1 + 0.113 * s1 - 0.02029 * c2 - 0.00504 * s2 + 0.01245 * c3
    - 0.06263 * s3 - 0.01709 * c4 - 0.008354 * s4 + 0.005645 * c6 + 0.0079 * s6;
  const l1 = -0.0001695 + 0.02689 * c1 + 0.01059 * s1 + 0.007855 * c2 + 0.01095 * s2;
  const l2 = 0.0008061 + 0.004294 * c3 - 0.01438 * s3;
  // ... and the shade functions that carry them
  const lm = 0.6709 - 0.3335 * x - 0.0197 * T2 + 0.005565 * T3 - 0.01094 * T4 - 0.01184 * T5
    - 0.009252 * T6 - 0.009624 * T7 - 0.002386 * T8;
  const lu0 = 0.218 - 0.0244 * x - 0.2126 * T2 + 0.0273 * T3 + 0.07759 * T4 - 0.02594 * T5 - 0.05404 * T6
    + 0.00005481 * T7 + 0.01406 * T8;
  const lu1 = 0.0843 + 0.2491 * x + 0.03057 * T2 - 0.2552 * T3 - 0.1153 * T4 + 0.08237 * T5 - 0.01092 * T6
    - 0.08349 * T7 - 0.03128 * T8;
  const lu2 = 0.144 + 0.1443 * x + 0.2141 * T2 + 0.1622 * T3 - 0.03552 * T4 + 0.02639 * T5 + 0.09068 * T6
    + 0.07781 * T7 + 0.03983 * T8;

  // chroma and hue: one value per pattern, the circles summed
  const z0 = -0.004368 + 0.1252 * c1 - 0.0641 * s1 - 0.01314 * c2 - 0.05796 * s2 + 0.006835 * c3
    + 0.03936 * s3 - 0.01485 * c4 + 0.005334 * s4 - 0.002967 * c5 - 0.006072 * s5
    - 0.003574 * c6 + 0.0109 * s6 + 0.008028 * c7 - 0.0004763 * s7;
  const z1 = 0.0004136 + 0.02092 * c1 + 0.05634 * s1 - 0.04041 * c2 - 0.0148 * s2 - 0.02298 * c3
    - 0.01026 * s3 - 0.00008119 * c6 + 0.006868 * s6 - 0.0007617 * c8 + 0.007896 * s8;
  const z2 = 0.002109 - 0.009001 * c1 + 0.01388 * s1 + 0.01012 * c2 - 0.0379 * s2 + 0.02635 * c3
    - 0.009689 * s3 - 0.007098 * c4 + 0.007541 * s4 - 0.006871 * c5 - 0.007151 * s5;
  // ... and the shade functions that carry them
  const xm = 0.1211 + 0.04137 * x - 0.07494 * T2 - 0.005489 * T3 + 0.01197 * T4 - 0.00311 * T5
    - 0.005955 * T6 + 0.0002794 * T7 - 0.001331 * T8;
  const xu0 = 0.1803 + 0.2658 * x - 0.09165 * T2 - 0.1527 * T3 + 0.04388 * T4 + 0.03206 * T5
    - 0.02226 * T6 - 0.01144 * T7 + 0.007307 * T8;
  const xu1 = 0.1138 - 0.0836 * x - 0.06853 * T2 + 0.0803 * T3 - 0.0155 * T4 - 0.008533 * T5
    + 0.002435 * T6 - 0.005645 * T7 - 0.001139 * T8;
  const xu2 = 0.1277 - 0.1845 * x - 0.1242 * T2 + 0.1803 * T3 + 0.05738 * T4 - 0.05716 * T5 - 0.01779 * T6
    + 0.02548 * T7 + 0.004899 * T8;
  const ym = 0.0001334 - 0.001965 * x - 0.0003443 * T2 + 0.001226 * T3 + 0.000008505 * T4
    + 0.0003938 * T5 + 0.00024 * T6 - 0.0001005 * T7 - 0.0001126 * T8;
  const yu0 = 0.008657 + 0.03764 * x + 0.005409 * T2 - 0.02471 * T3 - 0.003594 * T4 + 0.003626 * T5
    - 0.0004331 * T6 - 0.001905 * T7 - 0.0006617 * T8;
  const yu1 = -0.05245 - 0.298 * x - 0.04728 * T2 + 0.1858 * T3 + 0.0009324 * T4 - 0.05382 * T5
    + 0.001541 * T6 + 0.01896 * T7 + 0.001548 * T8;
  const yu2 = -0.008642 + 0.1688 * x + 0.01431 * T2 - 0.1165 * T3 + 0.0144 * T4 + 0.02857 * T5
    - 0.002197 * T6 - 0.008734 * T7 + 0.001013 * T8;

  const X = xm + xu0 * z0 + xu1 * z1 + xu2 * z2;
  const Y = ym + yu0 * z0 + yu1 * z1 + yu2 * z2;
  const h = hue + Math.atan2(Y, X) / R;
  return { l: lm + lu0 * l0 + lu1 * l1 + lu2 * l2, c: Math.hypot(X, Y), h: ((h % 360) + 360) % 360 };
}

/** The scale at hue `a`: the 11 Tailwind shades 50, 100, 200 … 900, 950. */
export function epicyclesCurve(a: number): { l: number; c: number; h: number }[] {
  return [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950].map((shade) => epicyclesAt(shade, a));
}
